create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.ARTBEW_MO_EK_CP_SUM_1 cluster by (
     MANDANT_ID,
     KJMO,
     WUP_BEREINIGT_FG 
)(
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_1 im DWH',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel_1 - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel_1 -> Counter +1',
	BEWART_ID NUMBER(38,0) NOT NULL COMMENT 'Bewegungsart ID. Bewegungsarten > 1000 beziehen sich auf Warenausgang, < 1000 auf Wareneingang',
	BEWART_DET_ID NUMBER(38,0) NOT NULL DEFAULT 9999 COMMENT 'Detaillierte Bewegungsart zum Aufbruch der bestehenden bewart_id',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_1 ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	GP_ID NUMBER(38,0) NOT NULL COMMENT 'Geschäftspartner - ID (Lieferanten - ID).Lieferant des Artikel_1-Markt innerhalb des Monats gem. Lieferantenfindung dbp_data.artbew_dat_ek_cp_sum.',
	KJMO NUMBER(38,0) NOT NULL COMMENT 'Monat_1 eines Kalenderjahres, Format JJJJMM',
	WRG_ID VARCHAR(3) NOT NULL COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	WUP_BEREINIGT_FG NUMBER(38,0) NOT NULL COMMENT 'Flag: Zeigt ob die Kennzahlen für diesen Markt in die \""bereinigte\"" Sicht einfließen dürfen, d.h. der Markt hatte in den letzten 12 Monaten vor dem Wochenbeginn der aktuellen Auwertung geöffnet und wird in der betrachteten Woche_1 nicht permanent geschlossen (zieht höchstens um).',
	POSTEN_ID VARCHAR(2) NOT NULL COMMENT 'Postenkennzeichen. Für Artikel_1, die nicht staendig im Sortiment sind. Angereichert jeweils aktuell aus dem historisierten Artikelstamm art_per.Wird für den Split der Wochenebene in Aggregat benötigt.',
	ZEK_ID VARCHAR(3) NOT NULL DEFAULT '-1' COMMENT 'Zentraleinkäufer - ID: Diese ID ist nicht mit der Mitarbeiter - ID identisch',
	EIGENMARKE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag Eigenmarke (wenn zek_id (Verhandler) und zek_vat_id (Verantwortlicher) in der Tabelle art_1 nicht identisch sind, wird das Flag auf 1 gesetzt (Eigenmarke-Artikel_1))',
	UMSATZ_NETTO NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'Umsatz vermindert um den Mehrwertsteuerbetrag',
	UMSATZ_NETTO_VJ NUMBER(38,4) NOT NULL DEFAULT 0 WITH MASKING POLICY #unknown_policy COMMENT 'Vorjahreswert - Umsatz vermindert um den Mehrwertsteuerbetrag ',
	BETRAG_KMEP NUMBER(38,4) NOT NULL DEFAULT 0 WITH MASKING POLICY #unknown_policy COMMENT 'Der Betrag KMEP (teilweise auch als WA-Bonus bezeichnet) ergibt sich aus der Differenz von EK4N zu EK2N multipliziert mit der Absatzmenge des gewählten Artikels in der gewählten Filiale in diesem Kalendermonat. Für die EK-Preise werden dazu nach Wareneingängen gewichtete Durchschnittspreise des Kalendermonats herangezogen. Die Logik unterscheidet sich hierbei zwischen DE (statische Variante mit Wareneinsatz + Boni zum Tag_1 des Abverkaufes) und KMO (dynamische Variante mit Wareneinsatz = Gleitender Durchschnitt + Boni als Durchschnittssatz aus verschiedenen Wareneingängen / Lieferanten).',
	BETRAG_KMEP_VJ NUMBER(38,4) NOT NULL DEFAULT 0 WITH MASKING POLICY #unknown_policy COMMENT 'Vergleichswert des Vorjahres - Der Betrag KMEP (teilweise auch als WA-Bonus bezeichnet) ergibt sich aus der Differenz von EK4N zu EK2N multipliziert mit der Absatzmenge des gewählten Artikels in der gewählten Filiale in diesem Kalendermonat. Für die EK-Preise werden dazu nach Wareneingängen gewichtete Durchschnittspreise des Kalendermonats herangezogen. Die Logik unterscheidet sich hierbei zwischen DE (statische Variante mit Wareneinsatz + Boni zum Tag_1 des Abverkaufes) und KMO (dynamische Variante mit Wareneinsatz = Gleitender Durchschnitt + Boni als Durchschnittssatz aus verschiedenen Wareneingängen / Lieferanten).',
	BETRAG_KMEP_O_FWU NUMBER(38,4) NOT NULL DEFAULT 0 WITH MASKING POLICY #unknown_policy COMMENT 'Der Betrag KMEP (teilweise auch als WA-Bonus bezeichnet) ohne Festwertumlage ergibt sich aus der Differenz von EK3N zu EK2N multipliziert mit der Absatzmenge des gewählten Artikels in der gewählten Filiale in diesem Kalendermonat. Für die EK-Preise werden dazu nach Wareneingängen gewichtete Durchschnittspreise des Kalendermonats herangezogen. Die Logik unterscheidet sich hierbei zwischen DE (statische Variante mit Wareneinsatz + Boni zum Tag_1 des Abverkaufes) und KMO (dynamische Variante mit Wareneinsatz = Gleitender Durchschnitt + Boni als Durchschnittssatz aus verschiedenen Wareneingängen / Lieferanten).',
	BETRAG_KMEP_O_FWU_VJ NUMBER(38,4) NOT NULL DEFAULT 0 WITH MASKING POLICY #unknown_policy COMMENT 'Vergleichswert des Vorjahres - Der Betrag KMEP (teilweise auch als WA-Bonus bezeichnet) ohne Festwertumlage ergibt sich aus der Differenz von EK3N zu EK2N multipliziert mit der Absatzmenge des gewählten Artikels in der gewählten Filiale in diesem Kalendermonat. Für die EK-Preise werden dazu nach Wareneingängen gewichtete Durchschnittspreise des Kalendermonats herangezogen. Die Logik unterscheidet sich hierbei zwischen DE (statische Variante mit Wareneinsatz + Boni zum Tag_1 des Abverkaufes) und KMO (dynamische Variante mit Wareneinsatz = Gleitender Durchschnitt + Boni als Durchschnittssatz aus verschiedenen Wareneingängen / Lieferanten).',
	LOGKOSTENZUSCHLAG NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'Logistikkostenzuschlag (ein kalkulierter Wert, der bei zentraler Lieferung Bestandteil einiger Einstandspreise ist)',
	LOGKOSTENZUSCHLAG_VJ NUMBER(38,4) DEFAULT 0 COMMENT 'Vorjahreswert - Logistikkostenzuschlag (ein kalkulierter Wert, der bei zentraler Lieferung Bestandteil einiger Einstandspreise ist)',
	WERBE_ABSCHRIFT_NETTO NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'Marktabschriften_1 durch Werbung (netto- vermindert um den Mehrwertsteuerbetrag)',
	WERBE_ABSCHRIFT_NETTO_VJ NUMBER(38,4) NOT NULL DEFAULT 0 COMMENT 'Vorjahreswert - Marktabschriften_1 durch Werbung (netto- vermindert um den Mehrwertsteuerbetrag)',
	PREIS_ABSCHRIFT_NETTO NUMBER(38,2) NOT NULL COMMENT 'Preisabschrift DE: marktabschriften_1 (abschriftart_id in (5,7); KMO:Filterung art_umbewertung_1 wie folgt: Mandant_1 2,5: preis_aend_grund_id in (7,10); Mandant_1 3: preis_aend_grund_id =11; Mandant_1 6: preis_aend_grund_id =2; Mandant_1 7,8: preis_aend_grund_id =7',
	PREIS_ABSCHRIFT_NETTO_VJ NUMBER(38,2) COMMENT 'Preisabschr.VJ DE: marktabschriften_1 (abschriftart_id in (5,7); KMO:Filterung art_umbewertung_1 wie folgt: Mandant_1 2,5: preis_aend_grund_id in (7,10); Mandant_1 3: preis_aend_grund_id =11; Mandant_1 6: preis_aend_grund_id =2; Mandant_1 7,8: preis_aend_grund_id =7',
	UMRECHNUNGSKURS_HIST NUMBER(38,5) NOT NULL DEFAULT 0 COMMENT 'Historischer Berichtskurs aus dbp_data.kurs_1 ',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	BETRAG_KMEP_INV_NETTO_KM NUMBER(38,5) WITH MASKING POLICY #unknown_policy COMMENT 'Der Betrag KMEP (teilweise auch als WA-Bonus bezeichnet) für die Inventur_1 innerhalb Warenbewegungen ergibt sich aus der Differenz von EK4N zu EK2N multipliziert mit der Absatzmenge des gewählten Artikels in der gewählten Filiale an diesem Tag. Die Absatzmenge menge_lagerbew_bme aus lagerbew_det_1 mit lager_bewart_id in (701,702,711,712,V30,V31,V32,V33,V35,V36,V37,V38,V45,V50,V54,W00,W02,W05,W10,W12,W15,W16,W17,W25,W27,W30).Für die EK-Preise werden dazu nach Wareneingängen gewichtete Durchschnittspreise der Kalenderwoche herangezogen. Die Logik unterscheidet sich hierbei zwischen DE (statische Variante mit Wareneinsatz + Boni zum Tag_1 des Abverkaufes) und KMO (dynamische Variante mit Wareneinsatz = Gleitender Durchschnitt + Boni als Durchschnittssatz aus verschiedenen Wareneingängen / Lieferanten).',
	constraint PK_ARTBEW_MO_EK_CP_SUM primary key (MANDANT_ID, ART_ID, BEWART_ID, BEWART_DET_ID, WUP_ID, NB_ID, KJMO, WRG_ID, WUP_BEREINIGT_FG, POSTEN_ID, GP_ID)
)COMMENT='PTY - EK-INT - Aggregat Artbew_1 auf Ebene Artikel_1 / Bewegungsart / Monat_1 mit Preisveränderung für Werbung (EK-Cockpit)'
;
